import java.io.IOException;
import java.nio.file.*;
import java.util.stream.Stream;

public class FileProcessingService {
    public void processSecurely(Path sourceDir, Path targetDir) throws IOException {
        Path resolvedTarget = targetDir.resolve("processed_data.csv");

        // Ensure target directory exists atomically
        Files.createDirectories(targetDir);

        // Copy with atomic replacement and attribute preservation
        Path tempFile = Files.copy(sourceDir.resolve("input.csv"), resolvedTarget,
            StandardCopyOption.REPLACE_EXISTING,
            StandardCopyOption.ATOMIC_MOVE);

        // Process lines with lazy stream evaluation, safely closed via try-with-resources
        try (Stream<String> lines = Files.lines(tempFile)) {
            long validRecords = lines.filter(line -> !line.startsWith("#")).count();
            System.out.println("Processed valid records: " + validRecords);
        } catch (IOException e) {
            System.err.println("Failed to parse file stream: " + e.getMessage());
            throw e;
        }
    }
}
